// Verifies X-AveronAi-Signature = hex HMAC-SHA256 of the *raw* JSON body, exactly
// as computed in infrastructure/webhooks/outbound-webhook.ts::signWebhookBody.
// Requires the Webhook node's Raw Body option (set above) so we sign the literal
// bytes the app sent, not a re-serialization of the parsed object — those can
// differ (key order, number formatting) even when they look identical.
const crypto = require('crypto');
const secret = $env.AVERONAI_WEBHOOK_SHARED_SECRET;
const item = $input.first();
const rawBody = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body); // fallback if Raw Body isn't available on this n8n version — see workflow note
const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
const provided = item.json.headers['x-averonai-signature'];
if (!provided || provided !== expected) {
  throw new Error('Invalid or missing x-averonai-signature header');
}
return [{ json: JSON.parse(rawBody) }];

// lead.matched fires the moment an /admin-configured alert rule's predicate
// matches — before any delivery attempt, already filtered server-side
// (domain/alerting/predicate.ts). No score/threshold filtering needed here;
// the DB row IS the filter, same 'operational config lives in /admin, not
// n8n' rule the app repo follows.
const d = $json.data;
const lines = d.leads.map((l) => {
  const budget = (l.budgetMin || l.budgetMax)
    ? `${l.budgetCurrency} ${l.budgetMin ?? '?'}\u2013${l.budgetMax ?? '?'}`
    : 'no budget stated';
  const contact = l.contact?.whatsapp || l.contact?.phone || l.contact?.email || 'no contact info';
  return `\u2022 *${l.name}* \u2014 ${l.leadType}, score ${l.buyerScore}, ${(l.locations || []).join(', ') || 'no location'}, ${budget} \u2014 ${contact}`;
}).join('\n');
const text = `\ud83d\udd25 *${d.ruleName}* matched ${d.leads.length} lead(s)\n${lines}`;
return [{ json: { text } }];

// alert.fired is the delivery CONFIRMATION (only sent once dispatch.ts's
// notifier.send() actually succeeds) — not a second copy of the same alert.
// The recipient here is the rule's configured recipient for `channel`
// (e.g. the agent's own WhatsApp for a whatsapp-channel rule); pinging that
// same person again via Cloud API would double-send them the alert, so this
// branch notifies WHATSAPP_OPS_PHONE_NUMBER (a supervisor/ops number) as an
// oversight copy instead, and separately logs the delivery to the audit sheet.
const d = $json.data;
const names = d.leads.map((l) => l.name).join(', ');
const whatsappText = `\u2705 "${d.ruleName}" delivered via ${d.channel} to ${d.recipient}\nLeads: ${names}`;
return [{
  json: {
    whatsappText,
    ruleName: d.ruleName,
    channel: d.channel,
    recipient: d.recipient,
    leadCount: d.leads.length,
    leadNames: names,
    deliveredAt: $json.timestamp,
  },
}];
